 page.evaluate('''()=>{const f=window.__BRAAZA__.get();f.paused=true;f.time=3;f.clear();for(let i=0;i<80;i++)f.update(.016);f.render();}''')
 page.screenshot(path=str(ROOT/'previews/desktop.png'))
 page.evaluate('window.__BRAAZA__.get().paused=false')
 page.mouse.move(720,440);page.mouse.wheel(0,440);page.wait_for_timeout(1100)
