 page.mouse.down();page.mouse.move(720,250,steps=12);page.mouse.up();page.wait_for_timeout(700)
 check('drag advances without opening viewer',page.evaluate('window.__BRAAZA__.inspect().position>1 && !document.querySelector("#viewer").open'))
