 page.locator('#scene').focus();page.keyboard.press('Home');page.wait_for_function('Math.abs(window.__BRAAZA__.get().cards[1].y-4.1)<.0001',timeout=20000)
 check('Home resets gallery and chain travel',page.evaluate('window.__BRAAZA__.get().motion.value===0 && window.__BRAAZA__.get().motion.travel===0'))
